// Concatenate supabase/migrations/*.sql into one script, in filename order, for
// pasting into the Supabase SQL editor. Reports file count and total size.
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const out = process.argv[2] ?? "supabase/COMBINED_SCHEMA.sql";

const files = readdirSync(dir)
  .filter((f) => f.endsWith(".sql"))
  .sort();

let combined = `-- SSC Mentor AI — full database schema
-- Generated by scripts/bundle-schema.mjs from supabase/migrations/
-- ${files.length} migrations, in filename (chronological) order.
--
-- Apply with: supabase db push     (after: npx supabase login)
-- or paste this whole file into the Supabase dashboard SQL editor.
`;

let bytes = 0;
for (const f of files) {
  const sql = readFileSync(join(dir, f), "utf8");
  bytes += statSync(join(dir, f)).size;
  combined += `\n\n-- ${"=".repeat(70)}\n-- ${f}\n-- ${"=".repeat(70)}\n${sql}`;
}

writeFileSync(out, combined);

console.log(`${files.length} migrations combined`);
console.log(`  source     ${(bytes / 1024).toFixed(0)} KB`);
console.log(`  combined   ${(combined.length / 1024).toFixed(0)} KB`);
console.log(`  written to ${out}`);
console.log(`\nfirst and last:`);
console.log(`  ${files[0]}`);
console.log(`  ${files[files.length - 1]}`);